def greedy_solve(max_attempts=1000):
    for attempt in range(max_attempts):
        random.seed(attempt)

        # Track pair usage
        pair_count = [[0]*num_golfers for _ in range(num_golfers)]

        weeks = []
        valid = True

        for w in range(num_weeks):
            # Greedily assign golfers to groups
            remaining = list(range(num_golfers))
            random.shuffle(remaining)
            week_groups = []

            for g in range(num_groups):
                group = []
                for p in remaining:
                    if len(group) == group_size:
                        break
                    # Check if p can join this group
                    can_join = True
                    for member in group:
                        if pair_count[member][p] > 0:
                            can_join = False
                            break
                    if can_join:
                        group.append(p)

                if len(group) != group_size:
                    valid = False
                    break

                # Update pair counts
                for p1, p2 in combinations(group, 2):
                    pair_count[p1][p2] += 1
                    pair_count[p2][p1] += 1

                week_groups.append(group)
                for p in group:
                    remaining.remove(p)

            if not valid:
                break
            weeks.append(week_groups)

        if valid:
            print(f"Found solution on attempt {attempt}!")
            return weeks

    return None

