def solve_social_golfers():
    # Represent solution as: schedule[w][p] = group of golfer p in week w
    schedule = [[-1]*num_golfers for _ in range(num_weeks)]

    # Track pairs: pair_used[p1][p2] = True if p1 and p2 have been in same group
    pair_used = [[False]*num_golfers for _ in range(num_golfers)]

    # For each week, track which golfers are in which group
    week_group_members = [[[] for _ in range(num_groups)] for _ in range(num_weeks)]

    def backtrack(week, golfer):
        if week == num_weeks:
            return True

        if golfer == num_golfers:
            return backtrack(week + 1, 0)

        # Try assigning golfer to each group
        for g in range(num_groups):
            # Check if group is full
            if len(week_group_members[week][g]) >= group_size:
                continue

            # Check if golfer can join this group (no pair conflicts)
            can_join = True
            for member in week_group_members[week][g]:
                if pair_used[golfer][member]:
                    can_join = False
                    break

            if can_join:
                # Assign golfer to group
                schedule[week][golfer] = g
                week_group_members[week][g].append(golfer)

                # Update pair usage
                for member in week_group_members[week][g][:-1]:
                    pair_used[golfer][member] = pair_used[member][golfer] = True

                if backtrack(week, golfer + 1):
                    return True

                # Backtrack
                for member in week_group_members[week][g][:-1]:
                    pair_used[golfer][member] = pair_used[member][golfer] = False
                week_group_members[week][g].pop()
                schedule[week][golfer] = -1

        return False

    return backtrack(0, 0), schedule

