def local_search(max_iter=100000):
    random.seed(42)

    # Initialize random schedule
    schedule = []
    for w in range(num_weeks):
        golfers = list(range(num_golfers))
        random.shuffle(golfers)
        week = [0]*num_golfers
        for i, p in enumerate(golfers):
            week[p] = i // group_size
        schedule.append(week)

    def count_violations():
        violations = 0
        pair_count = [[0]*num_golfers for _ in range(num_golfers)]
        for w in range(num_weeks):
            for p1 in range(num_golfers):
                for p2 in range(p1+1, num_golfers):
                    if schedule[w][p1] == schedule[w][p2]:
                        pair_count[p1][p2] += 1
        for p1 in range(num_golfers):
            for p2 in range(p1+1, num_golfers):
                if pair_count[p1][p2] > 1:
                    violations += pair_count[p1][p2] - 1
        return violations

    def get_pair_count():
        pair_count = [[0]*num_golfers for _ in range(num_golfers)]
        for w in range(num_weeks):
            for p1 in range(num_golfers):
                for p2 in range(p1+1, num_golfers):
                    if schedule[w][p1] == schedule[w][p2]:
                        pair_count[p1][p2] += 1
                        pair_count[p2][p1] += 1
        return pair_count

    v = count_violations()
    print(f"Initial violations: {v}")

    for iteration in range(max_iter):
        if v == 0:
            print(f"Found solution at iteration {iteration}!")
            return schedule

        # Pick a random week and swap two golfers' groups
        w = random.randint(0, num_weeks - 1)
        p1 = random.randint(0, num_golfers - 1)
        p2 = random.randint(0, num_golfers - 1)

        if schedule[w][p1] == schedule[w][p2]:
            continue

        # Try swap
        g1, g2 = schedule[w][p1], schedule[w][p2]
        schedule[w][p1], schedule[w][p2] = g2, g1

        new_v = count_violations()

        if new_v <= v:
            v = new_v
        else:
            # Revert with some probability (simulated annealing)
            if random.random() < 0.01:
                v = new_v
            else:
                schedule[w][p1], schedule[w][p2] = g1, g2

        if iteration % 10000 == 0:
            print(f"Iteration {iteration}, violations: {v}")

    print(f"Final violations: {v}")
    return None

