def solve_with_tabu(max_iter=200000):
    random.seed(123)

    # Initialize: each week is a random partition
    schedule = []
    for w in range(num_weeks):
        golfers = list(range(num_golfers))
        random.shuffle(golfers)
        week = [0]*num_golfers
        for i, p in enumerate(golfers):
            week[p] = i // group_size
        schedule.append(week)

    def compute_pair_matrix():
        """Compute how many times each pair appears together"""
        pm = [[0]*num_golfers for _ in range(num_golfers)]
        for w in range(num_weeks):
            for p1 in range(num_golfers):
                for p2 in range(p1+1, num_golfers):
                    if schedule[w][p1] == schedule[w][p2]:
                        pm[p1][p2] += 1
                        pm[p2][p1] += 1
        return pm

    def compute_violations(pm):
        """Count total violations"""
        v = 0
        for p1 in range(num_golfers):
            for p2 in range(p1+1, num_golfers):
                if pm[p1][p2] > 1:
                    v += pm[p1][p2] - 1
        return v

    def try_swap(w, p1, p2, pm):
        """Try swapping p1 and p2's groups in week w, return delta in violations"""
        g1, g2 = schedule[w][p1], schedule[w][p2]
        if g1 == g2:
            return 0

        # Compute delta
        delta = 0

        # For p1: leaving g1, joining g2
        # Remove pairs with old group g1 members
        for p in range(num_golfers):
            if p != p1 and schedule[w][p] == g1:
                pm[p1][p] -= 1
                pm[p][p1] -= 1
                if pm[p1][p] == 1:
                    delta -= 1  # was 2, now 1, one less violation
                elif pm[p1][p] == 0:
                    delta -= 1  # was 1, now 0, one less violation

        # Add pairs with new group g2 members
        for p in range(num_golfers):
            if p != p2 and schedule[w][p] == g2:
                pm[p1][p] += 1
                pm[p][p1] += 1
                if pm[p1][p] == 2:
                    delta += 1  # was 1, now 2, one more violation
                elif pm[p1][p] == 1:
                    delta += 0  # was 0, now 1, no new violation

        # For p2: leaving g2, joining g1
        for p in range(num_golfers):
            if p != p2 and schedule[w][p] == g2:
                pm[p2][p] -= 1
                pm[p][p2] -= 1
                if pm[p2][p] == 1:
                    delta -= 1
                elif pm[p2][p] == 0:
                    delta -= 1

        for p in range(num_golfers):
            if p != p1 and schedule[w][p] == g1:
                pm[p2][p] += 1
                pm[p][p2] += 1
                if pm[p2][p] == 2:
                    delta += 1
                elif pm[p2][p] == 1:
                    delta += 0

        return delta

    def apply_swap(w, p1, p2):
        g1, g2 = schedule[w][p1], schedule[w][p2]
        schedule[w][p1], schedule[w][p2] = g2, g1

    pm = compute_pair_matrix()
    v = compute_violations(pm)
    print(f"Initial violations: {v}")

    tabu = {}
    best_v = v
    best_schedule = [w[:] for w in schedule]

    for iteration in range(max_iter):
        if v == 0:
            print(f"Found solution at iteration {iteration}!")
            return schedule

        # Find best move
        best_delta = float('inf')
        best_move = None

        # Sample moves for efficiency
        moves = []
        for _ in range(500):
            w = random.randint(0, num_weeks - 1)
            p1 = random.randint(0, num_golfers - 1)
            p2 = random.randint(0, num_golfers - 1)
            if schedule[w][p1] != schedule[w][p2]:
                moves.append((w, p1, p2))

        for (w, p1, p2) in moves:
            tabu_key = (w, p1, p2)
            if tabu_key in tabu and tabu[tabu_key] > iteration:
                continue

            delta = try_swap(w, p1, p2, pm)
            if delta < best_delta:
                best_delta = delta
                best_move = (w, p1, p2)

        if best_move is None:
            continue

        w, p1, p2 = best_move
        apply_swap(w, p1, p2)
        v += best_delta

        # Update tabu
        tabu[(w, p1, p2)] = iteration + 10
        tabu[(w, p2, p1)] = iteration + 10

        if v < best_v:
            best_v = v
            best_schedule = [w[:] for w in schedule]

        if iteration % 50000 == 0:
            print(f"Iteration {iteration}, violations: {v}, best: {best_v}")

    print(f"Final violations: {v}, best: {best_v}")
    if best_v == 0:
        return best_schedule
    return None

