for w in range(num_weeks):
    for p in range(num_golfers):
        solver.add(g[w][p] >= 0, g[w][p] <= 9)

# Each group has exactly 5 players per week
for w in range(num_weeks):
    for grp in range(num_groups):
        solver.add(Sum([If(g[w][p] == grp, 1, 0) for p in range(num_golfers)]) == 5)

# No pair in same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        same = Sum([If(And(g[w][p1] == g[w][p2]), 1, 0) for w in range(num_weeks)])
        solver.add(same <= 1)

print("Solving with Int encoding...")
start = time.time()
result = solver.check()
elapsed = time.time() - start
print(f"Result: {result}, time: {elapsed:.2f}s")

if result == sat:
    m = solver.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            solution.append(m[g[w][p]].as_long())

    # Verify
    violations = 0
    for w in range(num_weeks):
        counts = [0]*num_groups
        for p in range(num_golfers):
            counts[solution[w*50+p]] += 1
        if not all(c == 5 for c in counts):
            print(f"Week {w}: {counts}")

    pair_count = {}
    for w in range(num_weeks):
        for p1 in range(num_golfers):
            for p2 in range(p1+1, num_golfers):
                if solution[w*50+p1] == solution[w*50+p2]:
                    key = (p1, p2)
                    pair_count[key] = pair_count.get(key, 0) + 1

    violations = sum(1 for v in pair_count.values() if v > 1)
    print(f"Violations: {violations}")

    if violations == 0:
        print("VALID!")
    else:
        print("INVALID")
else:
    print("UNSAT")
